  ('00000000-0000-4000-b041-000000000001', '00000000-0000-4000-9001-000000000041', 'Dress Rehearsal Strategy – Core Banking Replacement (Release 1)', 'How the go-live cutover, data migration, reconciliation and fallback are rehearsed before Release 1 goes live.', 'draft', $j${"document_reference":"DR-STR-001","document_version":"1.0","document_owner":"Daniel Okafor","next_review_date":"2027-01-31","number_of_rehearsals":3,"first_rehearsal_date":"2027-02-13","final_rehearsal_date":"2027-03-20","purpose":"To prove that the go-live weekend can be completed within the window, with reconciled data and a working fallback, before the real cutover.","objectives":"Complete the cutover runbook within the planned window\nReconcile migrated data to zero differences\nProve the fallback to the legacy systems\nTrain every participant on their runbook steps","scope":"Technical cutover\nData migration windows 1 and 2\nReconciliation and business verification\nGo/no-go decision points\nFallback","out_of_scope":"Post go-live hypercare","assumptions":"Pre-production is production-sized\nMock 3 has completed","constraints":"Rehearsals run over weekends\nProduction freeze rules apply to rehearsals","rehearsal_types":["full_dress_rehearsal","timed_cutover_rehearsal","rollback_rehearsal","business_validation_rehearsal"],"rehearsal_approach":"Three timed rehearsals in pre-production, each following the latest cutover runbook. Timings, issues and decisions are logged; the runbook is updated after each rehearsal.","rehearsal_schedule":"Dress rehearsal 1\t2027-02-13\tStatic window (window 1)\tPre-production\tPlanned\nDress rehearsal 2\t2027-03-06\tFinancial window (window 2) with reconciliation\tPre-production\tPlanned\nDress rehearsal 3\t2027-03-20\tFull timed rehearsal with business sign-off and fallback\tPre-production\tPlanned","environment":"Pre-production (production-sized)","data_set_used":"Production extract taken one week before each rehearsal, migrated with the Mock 3 tooling","production_data_volume":6500000,"environment_prerequisites":"Pre-production refreshed with production configuration\nInterfaces pointed at test endpoints\nBackups taken before each rehearsal","runsheet_reference":"CUT-RS-001 (cutover runbook)","timing_targets":"Static data load\t12 hours\tRunbook timestamps\nFinancial data load\t18 hours\tRunbook timestamps\nReconciliation\t8 hours\tFinance sign-off time\nFallback\t6 hours\tFallback runbook","participants":"Cutover manager\tNorthbridge Bank\tRuns the rehearsal and the timeline\nData migration team\tNorthbridge Bank and partner\tLoads and reconciliations\nFinance\tNorthbridge Bank\tFinancial reconciliation and sign-off\nVendor support\tPlatform vendor\tTechnical support on call","command_centre_used":true,"success_criteria":"Runbook completed within the window\nZero unreconciled differences\nGo/no-go points held on time\nFallback completed within 6 hours","metrics_captured":["duration_vs_plan","reconciliation_results","defects_found","rollback_time","data_quality"],"exit_criteria":"Two consecutive rehearsals within the window\nNo open critical defects\nBusiness sign-off of rehearsal 3","lessons_learned_process":"A lessons-learned session within two working days of each rehearsal; actions are tracked to closure before the next rehearsal.","risks_mitigations":"Rehearsal overruns the window\tGo-live timeline not proven\tParallel load agents; extra rehearsal if needed\tFatima Bello\nKey staff unavailable at weekends\tSteps not rehearsed\tNamed deputies for every role\tDaniel Okafor","roles_and_responsibilities":"Cutover manager\tRuns the rehearsal and decision points\tDaniel Okafor\nData migration lead\tMigration loads and reconciliation\tFatima Bello\nFinancial controller\tFinancial reconciliation sign-off\tOlivia Banda\nTest manager\tBusiness verification\tMaria Fernandes","glossary":"Dress rehearsal\tFull, timed run of the go-live steps in a production-like environment\nFallback\tReturn to the legacy systems if the go-live cannot complete","appendices":"Appendix 1 – Cutover runbook\tCUT-RS-001\nAppendix 2 – Rehearsal log template\tDR-LOG-001","version_history":"0.1\t2026-10-05\tDaniel Okafor\tFirst draft\n1.0\t2026-11-02\tDaniel Okafor\tBaseline for approval","related_documents":"Cutover Strategy\nData Migration Strategy (LREG-2026-105)\nTesting Strategy"}$j$)
) AS v(id, register_id, title, description, status, vals)
CROSS JOIN public.projects p
WHERE p.project_code = 'SEED334-PRJ-08'
ON CONFLICT (id) DO NOTHING;

-- Check: sample records per register (10 each; 1 for the Dress Rehearsal Strategy).
SELECT l.register_key, count(*) AS records
FROM public.local_register_records r JOIN public.local_registers l ON l.id = r.register_id
WHERE r.register_id IN ('00000000-0000-4000-9001-000000000018'::uuid, '00000000-0000-4000-9001-000000000019'::uuid, '00000000-0000-4000-9001-00000000001a'::uuid, '00000000-0000-4000-9001-00000000001b'::uuid, '00000000-0000-4000-9001-00000000001c'::uuid, '00000000-0000-4000-9001-00000000001d'::uuid, '00000000-0000-4000-9001-000000000041'::uuid)
  AND r.is_deleted = FALSE
GROUP BY l.register_key ORDER BY l.register_key;
